<?php session_start(); include('database/config.php'); $email=$_POST['email']; $password=$_POST['password']; $role=$_POST['role']; if($role=='admin'){ $stmt=$conn->prepare("SELECT * FROM administrateurs WHERE email=?"); }else{ $stmt=$conn->prepare("SELECT * FROM agents WHERE email=?"); } $stmt->bind_param("s",$email); $stmt->execute(); $result=$stmt->get_result(); if($result->num_rows>0){ $user=$result->fetch_assoc(); if(password_verify($password,$user['mot_de_passe'])){ $_SESSION['user']=$user; $_SESSION['role']=$role; if($role=='admin'){header("Location: admin/dashboard.html");} else{header("Location: agent/dashboard.html");} }else{echo "Mot de passe incorrect";} }else{echo "Utilisateur non trouvé";} ?>